<template><AuthLayout><h1 class="auth-heading">{{ $t('auth.activateTitle') }}</h1><p class="auth-hint">{{ $t('auth.activateHint') }}</p><el-form label-position="top" @submit.prevent="submit"><el-form-item :label="$t('auth.activationCode')"><el-input v-model="code" autocomplete="one-time-code" /></el-form-item><el-form-item :label="$t('auth.password')"><el-input v-model="password" type="password" autocomplete="new-password" show-password /></el-form-item><el-form-item :label="$t('auth.confirmPassword')"><el-input v-model="confirmation" type="password" autocomplete="new-password" show-password /></el-form-item><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" /><el-button native-type="submit" type="primary" :loading="loading" class="submit">{{ $t('auth.activate') }}</el-button></el-form></AuthLayout></template>
<script setup lang="ts">
import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useI18n } from 'vue-i18n'; import { activateUser } from '../api/auth'; import AuthLayout from '../layouts/AuthLayout.vue'
const route=useRoute(),router=useRouter(),{t}=useI18n(); const code=ref(typeof route.query.code==='string'?route.query.code:''),password=ref(''),confirmation=ref(''),error=ref(''),loading=ref(false)
async function submit(){if(password.value!==confirmation.value){error.value=t('auth.passwordMismatch');return}loading.value=true;error.value='';try{await activateUser(code.value,password.value);await router.replace({name:'login',query:{activated:'1'}})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
</script>
